<?php require 'config.php';requireAdmin();$stats=['users'=>(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn(),'vehicles'=>(int)$db->query('SELECT COUNT(*) FROM vehicles')->fetchColumn(),'granted'=>(int)$db->query("SELECT COUNT(*) FROM access_events WHERE decision='GRANTED'")->fetchColumn(),'denied'=>(int)$db->query("SELECT COUNT(*) FROM access_events WHERE decision='DENIED'")->fetchColumn()];$rows=$db->query('SELECT v.*,u.name,u.email FROM vehicles v JOIN users u ON u.id=v.user_id ORDER BY v.id DESC')->fetchAll();$title='Administracija';require 'includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">ADMINISTRACIJA</p><h1>Pregled sistema</h1></div></div><div class="stats"><?php foreach($stats as $k=>$v):?><div class="stat"><b><?=$v?></b><span><?=e(['users'=>'Korisnika','vehicles'=>'Vozila','granted'=>'Odobrenih ulazaka','denied'=>'Odbijenih ulazaka'][$k])?></span></div><?php endforeach;?></div><section class="card"><h2>Registrovana vozila</h2><div class="table"><table><thead><tr><th>Tablica</th><th>Vlasnik</th><th>E-mail</th><th>Vozilo</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['plate'])?></b></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e(($r['make']??'').' · '.($r['color']??''))?></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'includes/footer.php';?>

